    [caseId] UNIQUEIDENTIFIER NOT NULL,
    [programmeHeadId] UNIQUEIDENTIFIER NULL,
    [proposedAdvisorId] UNIQUEIDENTIFIER NOT NULL,
    [requestedBy] UNIQUEIDENTIFIER NOT NULL,
