    [decisionNotes] NVARCHAR(MAX) NULL,
    [reason] NVARCHAR(MAX) NOT NULL,
    [decidedAt] DATETIME2(3) NULL,
    [requestedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_CASECHANGEREQUESTS_requestedAt] DEFAULT SYSUTCDATETIME(),
    [status] NVARCHAR(30) NOT NULL CONSTRAINT [DF_CASECHANGEREQUESTS_status] DEFAULT N'pending',
    CONSTRAINT [PK_CASECHANGEREQUESTS] PRIMARY KEY ([caseChangeRequestId]),
    CONSTRAINT [FK_CASECHANGEREQUESTS_caseId] FOREIGN KEY ([caseId]) REFERENCES [dbo].[CASES]([caseId]),
    CONSTRAINT [FK_CASECHANGEREQUESTS_programmeHeadId] FOREIGN KEY ([programmeHeadId]) REFERENCES [dbo].[ACCOUNTS]([accountId]),
    CONSTRAINT [FK_CASECHANGEREQUESTS_proposedAdvisorId] FOREIGN KEY ([proposedAdvisorId]) REFERENCES [dbo].[ACCOUNTS]([accountId]),
    CONSTRAINT [FK_CASECHANGEREQUESTS_requestedBy] FOREIGN KEY ([requestedBy]) REFERENCES [dbo].[ACCOUNTS]([accountId]),
    CONSTRAINT [CK_CASECHANGEREQUESTS_status] CHECK ([status] IN (N'pending', N'approved', N'rejected')),
    CONSTRAINT [CK_CASECHANGEREQUESTS_decisionNotes] CHECK ([status] <> N'rejected' OR [decisionNotes] IS NOT NULL)
);
GO

